package uz.plugin.ogg_record_player

/**
 * The API Dart calls through JNI (bindings in `lib/src/bindings/ogg_record_player_api.g.dart`, generated by
 * `dart run tool/jnigen.dart` from the compiled class). Only primitive, [String] and [ByteArray] types cross the
 * boundary; every call goes to the calling engine's [OggRecordPlayerHost].
 *
 * Results and failures come back through callbacks, failures as the shared [PlayerError] codes. Calls for an
 * engine that is not attached, or for an unknown id, answer `UNKNOWN` or do nothing.
 */
object OggRecordPlayerApi {

    /** State changes of every player; [errorCode] is set only for state 4 (failed). */
    interface PlayerListener {
        fun onStateChanged(
            playerId: Int,
            state: Int,
            position: Double,
            duration: Double,
            speed: Double,
            errorCode: String?,
        )
    }

    /** Recorder results, the same events and payloads as the former `onRecorder*` channel callbacks. */
    interface RecorderListener {
        fun onCanceled(recorderId: Int, reason: Int)

        fun onStartFailed(recorderId: Int, error: String)

        fun onFinished(recorderId: Int, durationMillis: Long, waveform: ByteArray)
    }

    /** Answers one `createFrom*` call. */
    interface CreateCallback {
        fun onCreated(playerId: Int)

        fun onFailed(code: String, message: String, details: String?)
    }

    /** [known] is false when the duration is unavailable; [seconds] is then meaningless. */
    interface DurationCallback {
        fun onDuration(known: Boolean, seconds: Double)
    }

    interface DoneCallback {
        fun onDone()
    }

    /** [status] is a `MicrophonePermission` code: 0 granted, 1 denied, 2 permanently denied, 3 never asked. */
    interface PermissionCallback {
        fun onResult(status: Int)
    }

    /**
     * Replaces the listeners of engine [engineId] (`PlatformDispatcher.instance.engineId`, or 0 when Dart has
     * none); a hot restart registers new ones. Other engines keep theirs.
     */
    @JvmStatic
    fun setListeners(engineId: Long, playerListener: PlayerListener, recorderListener: RecorderListener) {
        OggRecordPlayerHost.forEngine(engineId)?.setListeners(playerListener, recorderListener)
    }

    @JvmStatic
    fun createFromFile(engineId: Long, path: String, callback: CreateCallback) {
        val host = OggRecordPlayerHost.forEngine(engineId)
        if (host == null) detached(callback) else host.createFromFile(path, callback)
    }

    @JvmStatic
    fun createFromUrl(engineId: Long, url: String, callback: CreateCallback) {
        val host = OggRecordPlayerHost.forEngine(engineId)
        if (host == null) detached(callback) else host.createFromUrl(url, callback)
    }

    @JvmStatic
    fun createFromBytes(engineId: Long, bytes: ByteArray, callback: CreateCallback) {
        val host = OggRecordPlayerHost.forEngine(engineId)
        if (host == null) detached(callback) else host.createFromBytes(bytes, callback)
    }

    @JvmStatic
    fun warmUp(callback: DoneCallback) {
        OggRecordPlayerHost.warmUp(callback)
    }

    // Player and recorder ids are unique across engines, so the calls below find the engine that owns the id.

    @JvmStatic
    fun play(playerId: Int) {
        OggRecordPlayerHost.owning(playerId)?.play(playerId)
    }

    @JvmStatic
    fun pause(playerId: Int) {
        OggRecordPlayerHost.owning(playerId)?.pause(playerId)
    }

    /** Stops and releases the player; its id is invalid afterwards. */
    @JvmStatic
    fun stop(playerId: Int) {
        OggRecordPlayerHost.owning(playerId)?.stop(playerId)
    }

    @JvmStatic
    fun getDuration(playerId: Int, callback: DurationCallback) {
        val host = OggRecordPlayerHost.owning(playerId)
        if (host == null) callback.onDuration(false, 0.0) else host.getDuration(playerId, callback)
    }

    @JvmStatic
    fun setPlaybackSpeed(playerId: Int, speed: Double) {
        OggRecordPlayerHost.owning(playerId)?.setPlaybackSpeed(playerId, speed)
    }

    /** Returns the recorder id, or -1 when [path] is empty or engine [engineId] is not attached. */
    @JvmStatic
    fun createRecorder(engineId: Long, path: String): Int =
        OggRecordPlayerHost.forEngine(engineId)?.createRecorder(path) ?: -1

    /** Returns null once the recording was started, else an `OggOpusRecorderException` code. */
    @JvmStatic
    fun startRecord(recorderId: Int): String? {
        val host = OggRecordPlayerHost.owning(recorderId) ?: return "UNKNOWN"
        return host.startRecord(recorderId)
    }

    @JvmStatic
    fun stopRecord(recorderId: Int) {
        OggRecordPlayerHost.owning(recorderId)?.stopRecord(recorderId)
    }

    @JvmStatic
    fun destroyRecorder(recorderId: Int) {
        OggRecordPlayerHost.owning(recorderId)?.destroyRecorder(recorderId)
    }

    /** The microphone permission status code, see [PermissionCallback]; denied when [engineId] is not attached. */
    @JvmStatic
    fun microphonePermission(engineId: Long): Int =
        OggRecordPlayerHost.forEngine(engineId)?.microphone?.status() ?: MicrophonePermission.DENIED

    /** Shows the system prompt when Android still may, then answers the resulting status. */
    @JvmStatic
    fun requestMicrophonePermission(engineId: Long, callback: PermissionCallback) {
        val permission = OggRecordPlayerHost.forEngine(engineId)?.microphone
        if (permission == null) callback.onResult(MicrophonePermission.DENIED) else permission.request(callback)
    }

    /** Opens this app's system settings page; false when it could not be opened. */
    @JvmStatic
    fun openAppSettings(engineId: Long): Boolean =
        OggRecordPlayerHost.forEngine(engineId)?.microphone?.openAppSettings() ?: false

    private fun detached(callback: CreateCallback) {
        callback.onFailed("UNKNOWN", "Failed to create player", "the calling Flutter engine is not attached")
    }
}
